<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/src/bootstrap.php';
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Utilisateurs — MIARADI-TRAVEL</title>
<style>:root{--red:#922D20;--paper:#FBF8F5;--ink:#28201d;--muted:#756861;--line:#ded5ce}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,Arial,sans-serif}.wrap{max-width:1100px;margin:40px auto;padding:0 18px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}h1{font-size:32px;margin:0}p{color:var(--muted)}.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:22px;margin:22px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}label{display:block;font-weight:650;font-size:13px}input,select{width:100%;padding:12px;margin-top:6px;border:1px solid var(--line);border-radius:7px;font:inherit}button,.btn{background:var(--red);color:white;border:0;border-radius:7px;padding:12px 16px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block}button.secondary{background:white;color:var(--red);border:1px solid var(--red)}.msg{min-height:22px;color:var(--red)}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted)}.pill{display:inline-block;border-radius:20px;padding:3px 9px;background:#f4e9e4;color:var(--red);font-size:12px}@media(max-width:600px){.wrap{margin:24px auto}.panel{padding:16px}h1{font-size:26px}}</style></head><body><main class="wrap">
<div class="top"><div><h1>Gestion des utilisateurs</h1><p>Créez des comptes et gérez les niveaux d’accès de l’équipe MIARADI.</p></div><a class="btn" href="index.php">Retour au tableau de bord</a></div>
<section class="panel"><h2>Ajouter un utilisateur</h2><form id="create"><div class="grid"><label>Nom complet<input name="display_name" required maxlength="180" autocomplete="name"></label><label>E-mail professionnel<input name="email" type="email" required maxlength="254" autocomplete="email"></label><label>Mot de passe temporaire (12 caractères minimum)<input name="password" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label>Rôle<select name="role"><option value="manager">Gestionnaire</option><option value="editor">Éditeur</option><option value="super_admin">Super administrateur</option></select></label></div><p>Transmettez le mot de passe temporaire de manière sécurisée et demandez à l’utilisateur de le modifier après sa première connexion.</p><button type="submit">Créer le compte</button></form><p id="message" class="msg" role="status"></p></section>
<section class="panel"><h2>Comptes existants</h2><div class="tablewrap"><table><thead><tr><th>Utilisateur</th><th>E-mail</th><th>Rôle</th><th>Statut</th><th>Dernière connexion</th><th>Actions</th></tr></thead><tbody id="users"><tr><td colspan="6">Chargement…</td></tr></tbody></table></div></section>
</main><script>
(()=>{let csrf='';const $=s=>document.querySelector(s);const labels={super_admin:'Super administrateur',manager:'Gestionnaire',editor:'Éditeur'};
async function request(method='GET',body){const r=await fetch('../api/admin/session.php',{credentials:'same-origin'});const s=await r.json();if(!s.data?.authenticated){location.href='login.php';throw new Error('Connexion requise.')}csrf=s.data.csrfToken;
const res=await fetch('../api/admin/users.php',{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-Token':csrf},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data.data;}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function load(){try{const d=await request();$('#users').innerHTML=d.users.map(u=>'<tr><td>'+esc(u.display_name)+'</td><td>'+esc(u.email)+'</td><td><select data-role="'+u.id+'">'+Object.entries(labels).map(([v,l])=>'<option value="'+v+'" '+(u.role===v?'selected':'')+'>'+l+'</option>').join('')+'</select></td><td><span class="pill">'+(Number(u.is_active)===1?'Actif':'Désactivé')+'</span></td><td>'+esc(u.last_login_at||'Jamais')+'</td><td><button class="secondary" data-save="'+u.id+'">Enregistrer</button> <button data-active="'+u.id+'" data-enabled="'+(Number(u.is_active)===1?'1':'0')+'">'+(Number(u.is_active)===1?'Désactiver':'Réactiver')+'</button></td></tr>').join('')||'<tr><td colspan="6">Aucun utilisateur.</td></tr>';document.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{try{await request('PATCH',{id:Number(b.dataset.save),role:$('[data-role="'+b.dataset.save+'"]').value});$('#message').textContent='Rôle mis à jour.';await load()}catch(e){$('#message').textContent=e.message}});document.querySelectorAll('[data-active]').forEach(b=>b.onclick=async()=>{try{await request('PATCH',{id:Number(b.dataset.active),is_active:b.dataset.enabled!=='1'});$('#message').textContent='Statut mis à jour.';await load()}catch(e){$('#message').textContent=e.message}});}catch(e){$('#message').textContent=e.message;}}
$('#create').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const body=Object.fromEntries(f.entries());try{await request('POST',body);e.currentTarget.reset();$('#message').textContent='Compte créé avec succès.';await load()}catch(err){$('#message').textContent=err.message}});load();})();
</script></body></html>